// 1. 隐藏无关元素，优化阅读体验
const hideSelectors = ['.nav-fixed', '.respond', '.content-tabs', 'blockquote', 'form', '.page-navigator'];
hideSelectors.forEach(selector => {
    const elems = document.querySelectorAll(selector);
    elems.forEach(elem => elem.style.display = 'none');
});

// 2. 提取script中的普通图片URL并插入文章
const articles = document.querySelectorAll('article:not(.no-mask)');
articles.forEach(article => {
    const script = article.querySelector('script:contains(loadBannerDirect)');
    if (script) {
        const imgMatch = script.textContent.match(/loadBannerDirect\('(https:\/\/pic\.rymufc\.cn\/[^']+)'/);
        if (imgMatch && imgMatch[1]) {
            // 创建图片元素插入文章顶部
