Artplayer.PLAYBACK_RATE = [0.6, 1, 2, 4, 6];
Artplayer.FAST_FORWARD_TIME = 500;
Artplayer.MOBILE_DBCLICK_PLAY = false;
Artplayer.DBCLICK_FULLSCREEN = false;
Artplayer.TOUCH_MOVE_RATIO = 0.1;
// 生成唯一ID
function generateUniqueId() {
    return 'artplayer-' + Date.now() + '-' + Math.random().toString(36).slice(2, 9);
}

// 视频替换函数（带防抖）
let replaceTimeout;

function replaceVideos() {
    clearTimeout(replaceTimeout);
    replaceTimeout = setTimeout(() => {
        document.querySelectorAll('video').forEach(video => {
            try {

                // 获取视频源
                const videoSrc = video.currentSrc || video.getAttribute('src');
                if (!videoSrc) return;
                        const posterSrc = video.poster || video.getAttribute('poster') || '';

                // 创建容器（继承样式）
                var container = document.createElement('div');
                container.id = generateUniqueId();
                container.style.width = '100%';
                //container.className = video.className;
                container.style.aspectRatio = '16/9';

                // 替换元素
                video.parentNode.replaceWith(container);

                // 初始化播放器（继承配置）
                var art = new Artplayer({
                    container: '#' + container.id,
                    url: videoSrc,
                    poster:posterSrc,
                    theme: '#ffad00',
                    autoplay: false,
                    muted: false,
                    fullscreen: true,
                    autoSize: true,
                    autoMini: false,
                    playbackRate: true,
                    setting: true,
                    lock: true,
                    gesture: true,
                    fastForward: true,
                    autoPlayback: true,
                    autoOrientation: true,
                });

                art.on('dblclick', (event) => {
                    event.stopImmediatePropagation();
                    event.stopPropagation();
                    event.preventDefault();
                    const tmz = +"20";
                    const clix = event.clientX;
                    const rwid = art.rect.width;
                    if (clix < rwid / 3) art.backward = tmz;
                    else if (clix > rwid * 2 / 3) art.forward = tmz;
                    else art.toggle();
                });

            } catch (e) {
                console.log('🌈🌈🌈ArtPlayer init error:' + e);
            }
        });
    }, 100);
}

// 初始执行
replaceVideos();

// 页面卸载时清理
window.addEventListener('beforeunload', () => {
    clearTimeout(replaceTimeout);
});

