(function () {
    // 适配多ID容器，兼容不同文章页
    const xpaths = [
        '//div[starts-with(@id, "post-card-")]/div[@class="blog-background load-success"]',
        '//div[@class="blog-background load-success"]'
    ];
    let el = null;
    for (const xpath of xpaths) {
        el = document.evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
        if (el) break;
    }
    if (!el) {
        console.error("未找到目标图片元素");
        return;
    }
    const style = el.style.backgroundImage;
    if (!style) {
        console.error("未找到background-image样式");
        return;
    }
    // 兼容 &quot; 和 " 两种引号格式
    const reg = /data:image\/jpeg;base64,([^&quot;"]+)/;
    const match = style.match(reg);
    if (!match || match.length < 2) {
        console.error("未匹配到base64数据");
        return;
    }
    const base64Str = match[1];
    try {
        const byteCharacters = atob(base64Str);
        const byteNumbers = new Array(byteCharacters.length);
        for (let i = 0; i < byteCharacters.length; i++) {
            byteNumbers[i] = byteCharacters.charCodeAt(i);
        }
        const byteArray = new Uint8Array(byteNumbers);
        const blob = new Blob([byteArray], { type: 'image/jpeg' });
        const url = URL.createObjectURL(blob);
        const img = new Image();
        img.src = url;
        img.style.maxWidth = '100%';
        img.style.border = 'none';
        img.style.margin = '10px 0';
        // 插入到文章顶部
        const article = document.querySelector('article:not(.no-mask)');
        if (article) article.insertBefore(img, article.firstChild);
        else document.body.appendChild(img);
        console.log("Base64图片解码成功", url);
    } catch (e) {
        console.error("Base64解码失败", e);
    }
})();

