// 1. 隐藏无关元素，优化阅读体验
const hideSelectors = ['.nav-fixed', '.respond', '.content-tabs', 'blockquote', 'form', '.page-navigator'];
hideSelectors.forEach(selector => {
    const elems = document.querySelectorAll(selector);
    elems.forEach(elem => elem.style.display = 'none');
});

// 2. 提取script中的普通图片URL并插入文章
const articles = document.querySelectorAll('article:not(.no-mask)');
articles.forEach(article => {
    const script = article.querySelector('script:contains(loadBannerDirect)');
    if (script) {
        const imgMatch = script.textContent.match(/loadBannerDirect\('(https:\/\/pic\.rymufc\.cn\/[^']+)'/);
        if (imgMatch && imgMatch[1]) {
            // 创建图片元素插入文章顶部
            const img = document.createElement('img');
            img.src = imgMatch[1];
            img.style.maxWidth = '100%';
            img.style.margin = '10px 0';
            img.style.objectFit = 'contain';
            article.insertBefore(img, article.firstChild);
        }
    }

// 3. base64封面解析兜底
const bgBox = article.querySelector('.blog-background');
if(bgBox && bgBox.style.backgroundImage){
    const bgReg = /data:image\/jpeg;base64,([^"]+)/;
    const bgMatch = bgBox.style.backgroundImage.match(bgReg);
    if(bgMatch){
        let b64 = bgMatch[1];
        let byteArr = Uint8Array.from(atob(b64), c=>c.charCodeAt(0));
        let blob = new Blob([byteArr],{type:"image/jpeg"});
        let blobUrl = URL.createObjectURL(blob);
        let coverImg = document.createElement('img');
        coverImg.src = blobUrl;
