b=b.replace(/<p>[\s\S]*?<\/p>/,'');  // 移除简介段(已单独展示)
// 播放区: video 标签(原生HLS兜底) + hls.js 脚本(外部, webView可达753即生效)
var player='<div style="margin:12px 0;background:#000;border-radius:8px;overflow:hidden">'
+'<video id="vx" src="'+m3u8+'" controls="controls" playsinline="true" webkit-playsinline="true" preload="metadata" style="width:100%;display:block;max-height:60vh"></video></div>'
+'<script src="https://753.sllvlmfs.cc/usr/themes/haijiao3/assets/__base/js/hls.js?v=1786422166" defer><'+'/script>'
+'<script>window.addEventListener("load",function(){var v=document.getElementById("vx");if(!v||!window.Hls||!Hls.isSupported())return;var src=v.getAttribute("src");if(!src)return;try{var hls=new Hls();hls.loadSource(src);hls.attachMedia(v);}catch(e){}});<'+'/script>';
return '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><style>body{margin:0;padding:12px;background:#15161a;color:#d4d4d8;font-size:15px;line-height:1.75;font-family:system-ui,-apple-system,sans-serif}h1.title{font-size:16px;color:#fff;margin:4px 2px 12px;line-height:1.4}.intro{color:#9ca3af;font-size:13px;margin:0 0 12px;line-height:1.6}.content img{max-width:100%;height:auto;display:block;border-radius:8px;margin:10px auto}.defaultimg{text-align:center}</style></head><body>'
+(t?'<h1 class="title">'+t+'</h1>':'')
+(intro?'<div class="intro">'+intro+'</div>':'')
+'<div class="content">'+b+'</div>'
+player
+'</body></html>'})()

