            html.push('<div class="detail-box"><div class="detail-top"><img src="' + cover + '" onerror="this.style.display=\'none\'"><div class="detail-info"><h5>' + title + '</h5><p>年份：' + year + '</p><p>语言：' + lang + '</p></div></div><div class="detail-intro"><p>' + blurb + '</p></div></div>');
            html.push('<div class="skip-bar"><div class="skip-title">⚙ 播放设置（仅本剧，重新进入仍生效）</div><div class="skip-row"><label>片头(秒)</label><input id="skipOp" type="number" min="0" step="1" placeholder="0"><label>片尾(秒)</label><input id="skipEd" type="number" min="0" step="1" placeholder="0"><label>速度</label><input id="speedInput" type="number" min="0.5" max="3" step="0.1" placeholder="1.0"><button type="button" onclick="saveSkip()">💾 保存</button></div></div>');
            html.push('<div id="nowPlaying" class="now-playing">正在播放：-</div>');
            html.push('<div class="line-tabs" id="lineTabs"></div>');
            html.push('<div id="panels"></div>');
            html.push('<div class="history-bar"><button onclick="clearHistory()">🗑 清除本剧历史</button></div>');
            html.push('</div>');
            html.push('<script>');
            var scriptCode = [
                'var froms = ' + JSON.stringify(froms) + ';',
                'var urls = ' + JSON.stringify(urls) + ';',
                'var title = ' + JSON.stringify(title) + ';',
                'var bgImage = ' + JSON.stringify(bgImage) + ';',
                'var bgAlpha = ' + JSON.stringify(bgAlpha) + ';',
                'var vp = document.getElementById("videoPlayer");',
                'var playerBox = document.getElementById("playerBox");',
                'var lineTabs = document.getElementById("lineTabs");',
                'var panels = document.getElementById("panels");',
                'var nowPlaying = document.getElementById("nowPlaying");',
                'var gestureTip = document.getElementById("gestureTip");',
                'var currentLine = 0;',
                'var currentIndex = 0;',
                'var currentTitle = "";',
                'var playbackRate = 1;',
                'var skipOp = 0;',
                'var skipEd = 0;',
                'var pendingSeekTime = null;',
                'var pendingSeekDelta = 0;',
                'var lastSavedTime = 0;',
                'var longPressTimer = null;',
                'var longPressTriggered = false;',
                'var tempRateActive = false;',
                'var originalRate = 1;',
                'var startX = 0;',
                'var startY = 0;',
                'var seekStartTime = 0;',
                'function getStorageKey(){return "mcs_history_" + encodeURIComponent(title);}',
                'function getHistory(){try{var d=localStorage.getItem(getStorageKey());return d?JSON.parse(d):{};}catch(e){return{};}}',
                'function saveHistory(){var h={line:currentLine,index:currentIndex,title:currentTitle,time:0};var v=document.getElementById("videoPlayer");if(v)h.time=v.currentTime||0;try{localStorage.setItem(getStorageKey(),JSON.stringify(h));}catch(e){}}',
                'function clearHistory(){localStorage.removeItem(getStorageKey());nowPlaying.textContent="正在播放：-";alert("本剧历史已清除");}',
                'function updateNowPlaying(){var lineName=froms[currentLine]||("线路"+(currentLine+1));nowPlaying.textContent="正在播放："+lineName+" - "+(currentTitle||"未知");}',
                'function showLine(idx){currentLine=idx;var tabs=lineTabs.children;for(var i=0;i<tabs.length;i++)tabs[i].className=i===idx?"active":"";var ps=panels.children;for(var j=0;j<ps.length;j++)ps[j].className="line-panel"+(j===idx?" active":"");}',
                'function setActive(id){var btns=panels.querySelectorAll(".episode-box button");for(var i=0;i<btns.length;i++)btns[i].classList.remove("active");var btn=document.getElementById(id);if(btn){btn.classList.add("active");btn.classList.add("watched");}}',
                'function play(url,line,index,text){currentLine=parseInt(line);currentIndex=parseInt(index);currentTitle=text;setActive("ep_"+line+"_"+index);vp.src=url;vp.playbackRate=playbackRate;vp.play().catch(function(){});var loading=document.getElementById("playerLoading");loading.style.display="flex";loading.innerHTML="加载中...";vp.onloadeddata=function(){loading.style.display="none";if(pendingSeekTime!==null){vp.currentTime=pendingSeekTime;pendingSeekTime=null;}};vp.onerror=function(){loading.style.display="flex";loading.innerHTML="播放失败";};updateNowPlaying();window.scrollTo(0,0);}',
                'function buildUI(){for(var i=0;i<froms.length;i++){var tab=document.createElement("button");tab.textContent=froms[i];tab.className=i===0?"active":"";tab.onclick=function(idx){return function(){showLine(idx);};}(i);lineTabs.appendChild(tab);var panel=document.createElement("div");panel.className="line-panel"+(i===0?" active":"");panel.id="panel_"+i;var box=document.createElement("div");box.className="episode-box";var eps=urls[i].split("#");for(var j=0;j<eps.length;j++){var ep=eps[j].split("$");if(ep.length>=2){var btn=document.createElement("button");btn.textContent=ep[0];btn.id="ep_"+i+"_"+j;btn.dataset.url=ep[1];btn.dataset.line=i;btn.dataset.index=j;btn.onclick=function(){play(this.dataset.url,this.dataset.line,this.dataset.index,this.textContent);};box.appendChild(btn);}}panel.appendChild(box);panels.appendChild(panel);}}',
                'vp.addEventListener("ended",function(){var all=panels.querySelectorAll("#panel_"+currentLine+" .episode-box button");var idx=-1;for(var i=0;i<all.length;i++){if(all[i].classList.contains("active")){idx=i;break;}}if(idx>=0&&idx<all.length-1){all[idx+1].click();}else{var nextLine=currentLine+1;if(nextLine<froms.length){showLine(nextLine);var firstBtn=panels.querySelector("#panel_"+nextLine+" .episode-box button");if(firstBtn)firstBtn.click();}else{alert("🎬 全部播放完毕");}}});',
                'function loadSkip(){try{var d=localStorage.getItem(getStorageKey()+"_skip");if(d){var o=JSON.parse(d);skipOp=parseInt(o.op)||0;skipEd=parseInt(o.ed)||0;var sp=parseFloat(o.speed);if(!(sp>0))sp=1;playbackRate=sp;vp.playbackRate=sp;var io=document.getElementById("skipOp"),ie=document.getElementById("skipEd"),is=document.getElementById("speedInput");if(io)io.value=skipOp||"";if(ie)ie.value=skipEd||"";if(is)is.value=sp===1?"":sp;}}catch(e){}}',
                'function saveSkip(){var io=document.getElementById("skipOp"),ie=document.getElementById("skipEd"),is=document.getElementById("speedInput");var op=io?(parseInt(io.value)||0):0,ed=ie?(parseInt(ie.value)||0):0,sp=is?parseFloat(is.value):1;if(op<0)op=0;if(ed<0)ed=0;if(!(sp>0)||isNaN(sp))sp=1;skipOp=op;skipEd=ed;playbackRate=sp;vp.playbackRate=sp;try{localStorage.setItem(getStorageKey()+"_skip",JSON.stringify({op:op,ed:ed,speed:sp}));}catch(e){}}',
                'function skipCheck(){if(!vp.duration||!isFinite(vp.duration))return;try{if(skipOp>0&&vp.currentTime<skipOp&&!vp.seeking){vp.currentTime=skipOp;}if(skipEd>0&&vp.currentTime>=vp.duration-skipEd&&vp.currentTime<vp.duration){vp.currentTime=vp.duration;}}catch(e){}}',
                'vp.addEventListener("timeupdate",skipCheck);',
                'vp.addEventListener("timeupdate",function(){if(Math.abs(vp.currentTime-lastSavedTime)>5){saveHistory();lastSavedTime=vp.currentTime;}});',
                'setInterval(saveHistory,5000);',
                'window.addEventListener("beforeunload",saveHistory);',
                'function formatTime(sec){if(!isFinite(sec)||sec<0)sec=0;var m=Math.floor(sec/60);var s=Math.floor(sec%60);return (m<10?"0"+m:m)+":"+(s<10?"0"+s:s);}',
                'function showGestureTip(msg){gestureTip.textContent=msg;gestureTip.style.display="block";}',
                'function hideGestureTip(){gestureTip.style.display="none";}',
                'document.addEventListener("touchstart",function(e){if(e.target!==vp && e.target!==playerBox)return;if(e.touches.length!==1)return;startX=e.touches[0].clientX;startY=e.touches[0].clientY;seekStartTime=vp.currentTime||0;pendingSeekDelta=0;longPressTriggered=false;tempRateActive=false;clearTimeout(longPressTimer);longPressTimer=setTimeout(function(){longPressTriggered=true;tempRateActive=true;originalRate=playbackRate;playbackRate=Math.min(3,playbackRate+0.5);vp.playbackRate=playbackRate;showGestureTip("临时速度 "+playbackRate.toFixed(1)+"x，上下滑调整");},500);});',
                'document.addEventListener("touchmove",function(e){if(e.target!==vp && e.target!==playerBox)return;if(e.touches.length!==1)return;var dx=e.touches[0].clientX-startX;var dy=e.touches[0].clientY-startY;if(longPressTriggered){if(Math.abs(dy)>Math.abs(dx)){var delta=-dy;var steps=Math.round(delta/30);if(steps!==0){var newRate=playbackRate+steps*0.1;newRate=Math.max(0.5,Math.min(3,newRate));newRate=Math.round(newRate*10)/10;if(newRate!==playbackRate){playbackRate=newRate;vp.playbackRate=playbackRate;showGestureTip("临时速度 "+playbackRate.toFixed(1)+"x");}}}}else{if(Math.abs(dx)>Math.abs(dy)&&isFinite(vp.duration)){pendingSeekDelta=dx/10;var target=seekStartTime+pendingSeekDelta;target=Math.max(0,Math.min(vp.duration,target));showGestureTip("进度 "+formatTime(target)+" / "+formatTime(vp.duration));}}});',
                'document.addEventListener("touchend",function(e){if(e.target!==vp && e.target!==playerBox)return;clearTimeout(longPressTimer);if(tempRateActive){playbackRate=originalRate;vp.playbackRate=playbackRate;showGestureTip("已恢复速度 "+playbackRate.toFixed(1)+"x");tempRateActive=false;longPressTriggered=false;setTimeout(hideGestureTip,500);}else{if(pendingSeekDelta!==0&&isFinite(vp.duration)){var target=seekStartTime+pendingSeekDelta;target=Math.max(0,Math.min(vp.duration,target));vp.currentTime=target;}longPressTriggered=false;pendingSeekDelta=0;hideGestureTip();}});',
                'function applySettings(){',
                '  try{',
                '    var J = window.__java;',
                '    if(!J || !J.get) return;',
                '    var b = J.get("ft_bg") || "";',
                '    var a = parseFloat(J.get("ft_alpha") || "0");',
                '    if(isNaN(a)) a = 0;',
                '    a = Math.max(0, Math.min(100, a));',
                '    document.body.style.setProperty("--bg-alpha", (1 - a / 100).toFixed(3));',
                '    if(b){',
                '      document.body.style.backgroundImage = "url(" + b + ")";',
                '      document.body.style.backgroundSize = "cover";',
                '      document.body.style.backgroundAttachment = "fixed";',
                '    } else {',
                '      document.body.style.backgroundImage = "";',
                '      document.body.style.backgroundSize = "";',
                '      document.body.style.backgroundAttachment = "";',
                '    }',
                '  }catch(e){}',
                '}',
                'applySettings();',
                'setInterval(applySettings, 2000);',
                'document.addEventListener("visibilitychange", function(){ if(!document.hidden) applySettings(); });',
                'buildUI();',
                'loadSkip();',
                'function restoreHistory(){var h=getHistory();if(h.line!==undefined&&h.index!==undefined){showLine(parseInt(h.line));var btn=document.getElementById("ep_"+h.line+"_"+h.index);if(btn){if(h.time){pendingSeekTime=h.time;}btn.click();return;}}var firstBtn=panels.querySelector(".episode-box button");if(firstBtn)firstBtn.click();}',
                'restoreHistory();',
                // ===== 新增：全屏自动横屏 =====
                'function lockLandscape(){if(screen.orientation&&screen.orientation.lock){screen.orientation.lock("landscape").catch(function(){});}}',
                'function unlockOrientation(){if(screen.orientation&&screen.orientation.unlock){screen.orientation.unlock();}}',
                'document.addEventListener("fullscreenchange",function(){if(document.fullscreenElement){lockLandscape();}else{unlockOrientation();}});',
                'document.addEventListener("webkitfullscreenchange",function(){if(document.webkitFullscreenElement){lockLandscape();}else{unlockOrientation();}});'
            ].join('');
            html.push(scriptCode);
            html.push('</script></body></html>');
            res = html.join('');
        }
    }
} catch (e) {
    res = '<div style="color:red;">代码执行异常: ' + e.message + '</div>';
}
res;

