// ==UserScript==
// @name         全网通用弹窗&悬浮广告一键屏蔽
// @namespace    adBlockPopAll
// @version      1.0
// @description  拦截弹窗、遮罩广告、悬浮挂件、跳转弹窗、右下角广告、登录强制弹窗、页面漂浮广告
// @author       DIY
// @match        *://*/*
// @grant        none
// @run-at       document-start
// ==/UserScript==

(function() {
    'use strict';

    // 1. 通用广告关键词黑名单，命中直接移除节点
    const adKeyWords = ['popup','pop','弹窗','广告','adv','ad','sponsor','推广','浮窗','悬浮','客服','咨询','弹窗','mask','modal','遮罩','close-ad','banner','签到弹窗','限时','领取福利'];

    // 2. 高频广告标签、class、id 正则匹配
    const adReg = /(pop|adv|ad|banner|mask|modal|float|fixed|tip|notify|弹窗|广告|悬浮|客服|咨询|福利|限时领取)/i;

    // 移除广告节点函数
    function delAdNode(el) {
        if (!el || el.dataset?.adBlocked) return;
        el.dataset.adBlocked = "true";
        el.remove();
    }

    // 批量扫描页面现有广告
    function scanAds() {
        const allNodes = document.querySelectorAll('div,section,aside,iframe,span,img,a');
        allNodes.forEach(item=>{
            const className = item.className || '';
            const id = item.id || '';
            const outerHtml = item.outerHTML || '';
            const style = getComputedStyle(item);

            // 固定悬浮、弹窗特征：fixed绝对定位、层级超高z-index
            const isFixedFloat = (style.position === 'fixed' || style.position === 'absolute') && Number(style.zIndex) > 999;
            const matchAdText = adReg.test(className + id + outerHtml);

            // 匹配关键词直接删除
            if(isFixedFloat && matchAdText) delAdNode(item);
            if(adKeyWords.some(key=>className.includes(key)||id.includes(key))) delAdNode(item);
        })

        // 拦截强制遮罩全屏弹窗
        document.querySelectorAll('body > div').forEach(bdDiv=>{
            const st = getComputedStyle(bdDiv);
            if(st.position === 'fixed' && st.width === '100vw' && st.height === '100vh'){
                delAdNode(bdDiv);
            }
        })
    }

    // 拦截网页onload、定时器延时弹出广告
    const originSetTimeout = window.setTimeout;
    window.setTimeout = function(cb,time,...rest){
        // 屏蔽短时间触发弹窗定时器
        if(time > 100 && time < 4500){
            const cbStr = cb?.toString() || '';
            if(/open|popup|show|modal|广告|弹窗/.test(cbStr)) return;
        }
        return originSetTimeout(cb,time,...rest);
    }

    // 拦截window.open 恶意跳转弹窗
    window.open = function(){ return null; }

    // 监听后续动态加载广告（ajax、延时弹出）
    const observer = new MutationObserver(()=> scanAds());
    observer.observe(document.documentElement,{childList:true,subtree:true,attributes:true});

    // 多个时机执行扫描
    document.addEventListener('DOMContentLoaded',scanAds);
    window.addEventListener('load',scanAds);
    setInterval(scanAds,1200);

})();

