(function(){
  var doc = org.jsoup.Jsoup.parse(result);
  var title = '';
  var titleEl = doc.selectFirst('h1');
  if(titleEl) title = titleEl.text();
  var imgs = doc.select('section.erx-article-con img');
  var urls = [];
  var imgHtml = '';
  for(var i=0;i<imgs.size();i++){
    var img = imgs.get(i);
    var src = img.attr('src');
    if(!src) src = img.attr('data-src') || '';
    if(src){
      urls.push(src);
      imgHtml += '<img class="zoom-img" src="'+src+'" data-idx="'+(urls.length-1)+'" style="max-width:100%;display:block;margin:10px auto;cursor:zoom-in;" onclick="openZoom('+(urls.length-1)+')">';
    }
  }
  if(!title && urls.length===0) return '<p>暂无内容</p>';
  var html = '<div>';
  if(title) html += '<h2>'+title+'</h2>';
  html += imgHtml;
  html += '</div>';
  html += '<div id="zoomOverlay" style="position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.92);z-index:9999;display:none;align-items:center;justify-content:center;flex-direction:column;">'+
      '<img id="zoomImg" src="" style="max-width:95%;max-height:85%;object-fit:contain;cursor:auto;">'+
      '<div style="position:absolute;bottom:20px;left:0;width:100%;display:flex;justify-content:space-between;padding:0 20px;box-sizing:border-box;">'+
      '<button onclick="prevZoom()" style="padding:8px 16px;background:#fff;border:none;border-radius:4px;cursor:pointer;">上一张</button>'+
      '<button onclick="nextZoom()" style="padding:8px 16px;background:#fff;border:none;border-radius:4px;cursor:pointer;">下一张</button>'+
      '</div>'+
      '</div>';
  html += '<script>'+
      'var zoomUrls='+JSON.stringify(urls)+';'+
      'var zoomIndex=0;'+
      'function openZoom(idx){if(zoomUrls.length===0)return;zoomIndex=idx;document.getElementById("zoomImg").src=zoomUrls[idx];document.getElementById("zoomOverlay").style.display="flex";}'+
      'function closeZoom(){document.getElementById("zoomOverlay").style.display="none";}'+
      'function prevZoom(){if(zoomUrls.length===0)return;zoomIndex=(zoomIndex-1+zoomUrls.length)%zoomUrls.length;document.getElementById("zoomImg").src=zoomUrls[zoomIndex];}'+
      'function nextZoom(){if(zoomUrls.length===0)return;zoomIndex=(zoomIndex+1)%zoomUrls.length;document.getElementById("zoomImg").src=zoomUrls[zoomIndex];}'+
      'document.getElementById("zoomOverlay").addEventListener("click",function(e){if(e.target===this)closeZoom();});'+
      'var sx=0, overlay=document.getElementById("zoomOverlay");'+
      'overlay.addEventListener("touchstart",function(e){sx=e.touches[0].clientX;});'+
      'overlay.addEventListener("touchend",function(e){var dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>50){if(dx<0)nextZoom();else prevZoom();}});'+
      '<\/script>';
  return html;
})()

