   导致已填的分类整段丢失。这里只在「= 左边确实像字段名」时才认定是新字段。 */
function _fkIsKey(line) {
    var i = line.indexOf('=');
    if (i <= 0) return null;
    var k = line.substring(0, i);
    if (FKEY_UIKEYS.indexOf(k) > -1) return k;
    if (k.indexOf('/') > -1 || k.indexOf('::') > -1 || k.indexOf(':') > -1) return null;
    if (k.indexOf('?') > -1 || k.indexOf('&') > -1 || k.indexOf('.') > -1) return null;
    if (/[\s"'`<>\[\]{}|\\^]/.test(k)) return null;
    if (k.length > 12) return null;
    return k;
}

/* 直接解析 loginInfo 原始串，能还原被 getLoginInfoMap() 截断的多行值 */
function _fkRawMap() {
    var m = {};
    var src = _fkSrc();
    if (!src) return m;
    var raw = '';
    try { raw = src.getLoginInfo() + ''; } catch (e) { raw = ''; }
    if (!raw || raw == 'null' || raw == 'undefined') return m;
    var lines = String(raw).split(/[\r\n]+/);
    var cur = null;
    for (var i = 0; i < lines.length; i++) {
        var line = lines[i];
        if (!line.length) continue;
        var k = _fkIsKey(line);
        if (k) {
            cur = k;
            m[cur] = line.substring(line.indexOf('=') + 1);
        } else if (cur) {
            m[cur] = m[cur] + '\n' + line;
        }
    }
    return m;
}

/* 覆盖原 uinfo()：Map 结果 + 原始串补全，两者取更完整的那份 */
function uinfo() {
    var m = {};
    var src = _fkSrc();
    if (src) {
        var mm = null;
        try { mm = src.getLoginInfoMap(); } catch (e) { mm = null; }
        if (mm) {
            var got = false;
            try {
                var it = mm.keySet().iterator();
                while (it.hasNext()) {
                    var k = it.next() + '';
                    if (_fkBadKey(k)) continue;                  // 丢掉分类碎片
                    var v = mm.get(k);
                    m[k] = (v === null || v === undefined) ? '' : (v + '');
                }
                got = true;
            } catch (e2) { got = false; }
            if (!got) {
                try {
                    for (var kk in mm) {
                        if (kk == 'class' || kk == 'empty') continue;
                        if (_fkBadKey(kk)) continue;
                        m[kk] = mm[kk] + '';
                    }
                } catch (e3) {}
            }
        }
    }
    var rm = {};
    try { rm = _fkRawMap(); } catch (e4) { rm = {}; }
    for (var k2 in rm) {
        if (!Object.prototype.hasOwnProperty.call(rm, k2)) continue;
        var nv = rm[k2] + '';
        var ov = (m[k2] === undefined ? '' : m[k2] + '');
        if (nv && (!ov || nv.length > ov.length)) m[k2] = nv;
    }
    return m;
}

function _fkVal(v) {
    v = (v === undefined || v === null) ? '' : (v + '');
    return (v == 'undefined' || v == 'null') ? '' : v;
}

/* ArtPlayer 版本号：同步拉取 unpkg。
   原写法把它内联在 loginUi 里，一旦网络不可达就抛异常，导致整个登录界面渲染失败（0 控件）。
   这里包了 try/catch，失败返回 '?'。 */
function apver() {
    try {
        var s = java.importScript('https://unpkg.com/artplayer/dist/artplayer.js');
        var v = s && String(s).match(/artplayer\.js.*v([0-9][^\s"']*)/i);
        return v ? v[1] : '?';
    } catch (e) { return '?'; }
}

/* 判断是否为「分类碎片」key。
   分类网址里带 ?t=1 时，legado 的 getLoginInfoMap() 会把整行当成新字段存进来
   （key = "演员A::https://...?t"）。这些碎片必须剔除，否则回写 loginInfo 时会污染数据。 */
function _fkBadKey(k) {
    k = String(k || '');
    if (!k) return true;
    if (FKEY_UIKEYS.indexOf(k) > -1) return false;
    if (k.indexOf('::') > -1) return true;
    if (k.indexOf('/') > -1) return true;
    if (k.indexOf('?') > -1 || k.indexOf('&') > -1) return true;
    if (k.indexOf('.') > -1) return true;
    if (k.indexOf('=') > -1) return true;
    return false;
}

/* 读「自定义分类」原文：loginInfo 与源变量 fkey 两路，取「能解析出更多条目」的那份。
   注意不能简单取更长的——归一化后两条内容常常重复，取更长会得到重复来源。 */
function fkeyRaw() {
    var a = '';
    try { a = _fkVal(uinfo()[FKEY_NAME]); } catch (e) { a = ''; }
    var b = '';
    var src = _fkSrc();
    if (src) { try { b = _fkVal(src.get('fkey')); } catch (e2) { b = ''; } }
    if (!String(a).trim()) return b;
    if (!String(b).trim()) return a;
    try { return (fkeyCount(b) > fkeyCount(a)) ? b : a; } catch (e3) { return a; }
}

/* 归一化成「单条一行、用 ; 分隔」的单行串 */
function fkeyNorm(raw) {
    raw = (raw || '') + '';
    if (raw == 'undefined' || raw == 'null') raw = '';
    if (!String(raw).trim()) return '';
    var items = String(raw).split(/[\r\n,，;；|]+/);
    var out = [];
    for (var i = 0; i < items.length; i++) {
        var t = String(items[i] || '').replace(/^[\s"'“”`]+|[\s"'“”`]+$/g, '');
        if (t) out.push(t);
    }
    if (out.length < 2 && /\s/.test(raw)) {
        var t2 = String(raw).trim().split(/\s+/);
        var o2 = [];
        for (var j = 0; j < t2.length; j++) if (t2[j]) o2.push(t2[j]);
        if (o2.length > out.length) out = o2;
    }
    return out.join(';');
}

function _fkNameOf(url, i) {
    var seg = String(url).replace(/\/+$/, '').split('/').pop();
    if (!seg || /^(?:page|\d+)(?:\.html)?$/i.test(seg)) {
        var tmp = String(url).replace(/\/+$/, '').split('/');
        seg = tmp.length > 1 ? tmp[tmp.length - 2] : '';
    }
    seg = String(seg || '').replace(/\.html$/i, '');
    try { seg = decodeURIComponent(seg); } catch (e) {}
    return seg || ('分类' + (i + 1));
}

/* 把原始文本切成条目列表（不生成最终 URL） */
function fkeyItems(raw) {
    raw = (raw || '') + '';
    if (raw == 'undefined' || raw == 'null') raw = '';
    if (!String(raw).trim()) return [];
    var items = String(raw).split(/[\r\n,，;；|]+/);
    var list = [];
    for (var i = 0; i < items.length; i++) {
        var t = String(items[i] || '').replace(/^[\s"'“”`]+|[\s"'“”`]+$/g, '');
        if (t) list.push(t);
    }
    if (list.length < 2 && /\s/.test(raw)) {
        var t2 = String(raw).trim().split(/\s+/);
        var l2 = [];
        for (var j = 0; j < t2.length; j++) if (t2[j]) l2.push(t2[j]);
        if (l2.length > list.length) list = l2;
    }
    var out = [];
    for (var n = 0; n < list.length; n++) {
        var item = list[n];
        var name = '', url = '';
        var p = item.indexOf('::');
        if (p > -1) { name = item.substring(0, p).trim(); url = item.substring(p + 2).trim(); }
        else { url = item; }
        if (!/[\/\.]/.test(url)) continue;                       // 纯文字碎片，丢弃
        url = url.replace(/^\s*(?:https?:)?\/\/[^\/]+/i, '').replace(/\s+/g, '');
        if (!url) continue;
        if (url.charAt(0) != '/') url = '/' + url;
        var q = '';
        var qi = url.indexOf('?');
        if (qi > -1) { q = url.substring(qi + 1); url = url.substring(0, qi); }
        if (!name) name = _fkNameOf(url, n);
        name = String(name).replace(/[:：\r\n]/g, '').trim() || ('分类' + (n + 1));
        out.push({ name: name, url: url, q: q });
    }
    return out;
}

/* 条目 → sortUrl 行 */
function fkeyRow(it) {
    var url = it.url, q = it.q, body;
    if (/\/page\.html$/i.test(url) || /\/\d+\.html$/i.test(url)) {
        body = '"' + url.replace(/\/(?:page|\d+)\.html$/i, '/') + '"+page+".html"';
    } else if (/\/index\.html$/i.test(url)) {
        body = '"' + url + '?t="+page';
    } else if (/\.html$/i.test(url)) {
        body = '"' + url + '"';                                  // 日期页/固定页：单页
    } else if (/(?:^|&)t=/.test(q)) {
        body = '"' + url + '?t="+page';
    } else if (/\/$/.test(url)) {
        body = '"' + url + '"+page+".html"';
    } else {
        body = '"' + url + '/"+page+".html"';
    }
    return it.name + '::data:;base64,{{java.base64Encode(' + body + ')}},{"type":"18av"}';
}

function fkeyFrom(raw) {
    var items = fkeyItems(raw), out = [];
    for (var i = 0; i < items.length; i++) out.push(fkeyRow(items[i]));
    return out;
}

function fkeyCount(raw) {
    try { return fkeyItems(raw).length; } catch (e) { return 0; }
}

/* 解析成 sortUrl 行数组（sortUrl 与按钮都调它） */
function fkey() {
    try { return fkeyFrom(fkeyRaw()); } catch (e) { return []; }
}

/* 归一化 + 双写（源变量 fkey）。登录时会自动跑一次 */
function normFkey() {
    var raw = fkeyRaw();
    if (!String(raw).trim()) return 0;
    var single = fkeyNorm(raw);
    if (!single) return 0;
    var n = fkeyCount(single);
    var src = _fkSrc();
    if (!src) return n;
    try { src.put('fkey', single); } catch (e) {}
    if (raw.indexOf('\n') < 0 && raw === single) return n;   // 已是单行，不冒险改 loginInfo
    var raw0 = '';
    try { raw0 = src.getLoginInfo() + ''; } catch (e2) { raw0 = ''; }
    if (!raw0 || raw0 == 'null' || raw0 == 'undefined') return n;
    try {
        var m = uinfo();
        var clean = {};
        for (var k in m) {
            if (!Object.prototype.hasOwnProperty.call(m, k)) continue;
            if (FKEY_UIKEYS.indexOf(k) < 0) continue;            // 只写真正的 UI 字段
            clean[k] = m[k];
        }
        clean[FKEY_NAME] = single;
        src.putLoginInfo(JSON.stringify(clean));
        // 校验只看 loginInfo 本身（不能用 uinfo()，它会被源变量兜底而掩盖失败）
        var back = '';
        try { back = _fkVal(_fkRawMap()[FKEY_NAME]); } catch (e3) {}
        if (back.indexOf(fkeyItems(single)[0].name) < 0 && back.indexOf(single.split(';')[0]) < 0) {
            try { src.putLoginInfo(raw0); } catch (e4) {}    // 回写失败则还原
        }
    } catch (e5) {}
    return n;
}

/* 诊断：把真实读到的一切弹出来，便于定位 */
function diagFkey() {
    var L = [];
    var src = _fkSrc();
    L.push('① source 对象：' + (src ? '可用' : '不可用'));
    var rawInfo = '(读不到)';
    try { rawInfo = src ? (src.getLoginInfo() + '') : '(无 source)'; } catch (e) { rawInfo = 'getLoginInfo() 异常: ' + e; }
    L.push('② loginInfo 原始串（前400字）：\n' + String(rawInfo).substring(0, 400));
    var keys = [];
    try { var mm = uinfo(); for (var k in mm) if (Object.prototype.hasOwnProperty.call(mm, k)) keys.push(k); } catch (e2) {}
    L.push('③ 解析到字段(' + keys.length + ')：' + keys.join(' / '));
    var v = fkeyRaw();
    L.push('④ 自定义分类 原文（前300字）：\n' + (String(v).trim() ? String(v).substring(0, 300) : '（空）'));
    var sv = '(空)';
    try { sv = src ? _fkVal(src.get('fkey')) : '(无 source)'; } catch (e3) {}
    L.push('⑤ 源变量 fkey（前300字）：\n' + (String(sv).trim() ? String(sv).substring(0, 300) : '（空）'));
    var arr = [];
    var err = '';
    try { arr = fkey(); } catch (e4) { err = e4 + ''; }
    if (err) L.push('⑥ 解析异常：' + err);
    else if (!arr.length) L.push('⑥ 解析结果：0 个（没识别出有效条目）');
    else {
        var names = [];
        for (var i = 0; i < arr.length; i++) names.push('  ' + (i + 1) + '. ' + arr[i].split('::')[0]);
        L.push('⑥ 解析结果：' + arr.length + ' 个\n' + names.join('\n'));
    }
    var txt = '🔧 自定义分类诊断\n\n' + L.join('\n\n');
    try { java.setClipboard(txt); } catch (e5) {}
    try { java.longToast('\n' + txt + '\n\n（已复制到剪贴板）'); } catch (e6) {}
    return txt;
}

/* 校验：告诉用户当前识别到什么 */
function checkFkey() {
    var raw = fkeyRaw();
    var tip;
    if (!String(raw).trim()) {
        tip = '❎ 没读到分类内容。\n\n'
            + '请按下面顺序操作：\n'
            + '1) 在上面的「自定义分类」框里填内容\n'
            + '2) 点右上角 √ 保存（很关键，不保存读不到）\n'
            + '3) 再回到本页点「🧪校验分类」\n\n'
            + '【格式】每行一个：\n分类名::网址\n\n'
            + '多个分类用 换行 / 分号 / 逗号 隔开都行。\n'
            + '在视频详情页长按简介里的分类或演员名，会自动复制成「名称::网址」。\n\n'
            + '还是不行就点右边的「🔧诊断」把结果发我。';
    } else {
        var arr = [];
        var err = '';
        try { arr = fkey(); } catch (e) { err = e + ''; }
        if (err) tip = '❎ 解析出错：' + err;
        else if (!arr.length) tip = '❎ 读到了内容，但没识别出有效条目：\n' + String(raw).substring(0, 300)
            + '\n\n每条要像这样：分类名::https://mjv006.com/zh/xxx/';
        else {
            var names = [];
            for (var i = 0; i < arr.length; i++) names.push('  ' + (i + 1) + '. ' + arr[i].split('::')[0]);
            tip = '✅ 已识别 ' + arr.length + ' 个分类：\n\n' + names.join('\n')
                + '\n\n返回后发现页生效（需重新进发现页）。';
        }
    }
    java.longToast('\n' + tip);
}

/* 备份：写入源变量，避免 loginInfo 读取异常时丢失 */
function saveFkey() {
    var n = 0;
    try { n = normFkey(); } catch (e) {}
    if (!n) { try { n = fkeyCount(fkeyRaw()); } catch (e0) {} }
    var raw = fkeyRaw();
    if (!String(raw).trim()) {
        java.longToast('\n❎ 读到的内容为空。\n请先填写 → 点右上角 √ 保存 → 再进本页点备份。\n\n若已保存仍读不到，点「🔧诊断」看原因。');
        return;
    }
    java.longToast('\n✅ 已备份 ' + n + ' 条：\n\n' + String(raw).substring(0, 300)
        + '\n\n备份内容存在源变量 fkey 里，即使登录信息丢失也能恢复。');
}

/* 清空备份 */
function clearFkey() {
    var src = _fkSrc();
    try { if (src) src.put('fkey', ''); } catch (e) {}
    java.longToast('\n✅ 已清空备份的自定义分类。\n（发现页会只剩内置分类，登录框里的内容不受影响）');
}
/* =============== [自定义分类 · 修复块 end] =============== */

