        cache.delete("${url}");
    }
  }
const u = srcurl;
const uok = (typeof u === 'string' && u.length > 9 && (u.indexOf('http:') === 0 || u.indexOf('https:') === 0));
const _tip = function (m) { try { java.longToast(m); } catch (e) {} };

function _ensureDiagBox() {
    var box = document.getElementById('av18diag');
    if (!box) {
        box = document.createElement('div');
        box.id = 'av18diag';
        box.className = 'av18-diag';
