}
function _diag(obj) {
    window.__diag = obj;
    try { obj['页面地址'] = location.href; } catch (e0) {}
    try { obj['页面错误'] = window.__err || []; } catch (e) {}
    try { console.log('AV18DIAG ' + JSON.stringify(obj)); } catch (e2) {}
    try {
        var box = _ensureDiagBox();
        box.textContent = '诊断信息（可截图发给开发者）' + String.fromCharCode(10) + JSON.stringify(obj, null, 1);
        box.style.display = 'block';
    } catch (e3) {}
    return obj;
}

/* ================= 播放器核心：hls.js + 原生 video ================= */
const HLS_CDN = [
    'https://cdn.jsdelivr.net/npm/hls.js@1.5.17/dist/hls.min.js',
    'https://unpkg.com/hls.js@1.5.17/dist/hls.min.js',
    'https://cdnjs.cloudflare.com/ajax/libs/hls.js/1.5.17/hls.min.js',
    'https://cdn.bootcdn.net/ajax/libs/hls.js/1.5.17/hls.min.js'
];
const _NL = String.fromCharCode(10);

function _abs(base, p) {
    p = String(p == null ? '' : p);
    if (!p) return p;
    if (p.indexOf('http:') === 0 || p.indexOf('https:') === 0) return p;
    try { return new URL(p, base).href; } catch (e) {}
    while (p.charAt(0) === '/') p = p.substring(1);
    var i = base.lastIndexOf('/');
    var dir = i > 0 ? base.substring(0, i + 1) : base + '/';
    return dir + p;
}
function _loadJs(src, ms) {
    return new Promise(function (res, rej) {
        var sc = document.createElement('script');
        var done = false;
        var t = setTimeout(function () { if (!done) { done = true; rej(new Error('超时')); } }, ms || 15000);
        sc.src = src;
        sc.onload = function () { if (!done) { done = true; clearTimeout(t); res(); } };
        sc.onerror = function () { if (!done) { done = true; clearTimeout(t); rej(new Error('加载失败')); } };
        document.head.appendChild(sc);
    });
}
async function _loadHls() {
    var errs = [];
    for (var i = 0; i < HLS_CDN.length; i++) {
        try {
            await _loadJs(HLS_CDN[i]);
            if (typeof Hls !== 'undefined') return { ok: HLS_CDN[i], errs: errs };
            errs.push(HLS_CDN[i] + ':已加载但无 Hls');
        } catch (e) { errs.push(HLS_CDN[i].replace('https://', '') + ':' + e.message); }
    }
    return { ok: null, errs: errs };
}
/* 把清单里的相对地址（含 AES key 的 URI）全部改写成绝对地址。
   实测 EXT-X-KEY 的 URI 是相对的 aavv.vv，不改的话喂 blob: 后 hls.js 解析不到，会 fragLoadError。 */
async function _absPlaylist(mu) {
    var r = await fetch(mu);
    if (!r.ok) throw new Error('清单 HTTP ' + r.status + '（无 Referer 时 CDN 返回 404）');
    var txt = await r.text();
    return txt.split(_NL).map(function (line) {
        var t = line.trim();
        if (!t) return line;
        if (t.charAt(0) === '#') {
            var k = t.indexOf('URI=');
            if (k < 0) return line;
            var q1 = t.indexOf(String.fromCharCode(34), k);
            var q2 = q1 < 0 ? -1 : t.indexOf(String.fromCharCode(34), q1 + 1);
            if (q1 < 0 || q2 <= q1) return line;
            return t.substring(0, q1 + 1) + _abs(mu, t.substring(q1 + 1, q2)) + t.substring(q2);
        }
        return _abs(mu, t);
    }).join(_NL);
}
/* 手势：双击左右快进 / 中间暂停，长按右侧倍速，横向拖动 Seek（替代 Artplayer 的那套） */
function _bindControls(v) {
    var FFV = ${_ff}, TMZ = ${_tz}, RATIO = 0.${_lv};
    if (!(FFV > 0)) FFV = 3;
    if (!(TMZ > 0)) TMZ = 10;
    if (!(RATIO > 0)) RATIO = 0.3;
    var pt = null, sx = 0, stime = 0;
    function rect() { return v.getBoundingClientRect(); }
    v.addEventListener('dblclick', function (ev) {
        var r = rect(), x = ev.clientX - r.left;
        if (x < r.width / 3) v.currentTime = Math.max(0, v.currentTime - TMZ);
        else if (x > r.width * 2 / 3) v.currentTime = v.currentTime + TMZ;
        else { if (v.paused) v.play(); else v.pause(); }
    });
    v.addEventListener('touchstart', function (ev) {
        if (!ev.touches || !ev.touches.length) return;
        var r = rect(), x = ev.touches[0].clientX - r.left;
        sx = x; stime = v.currentTime;
        if (x > r.width * 0.72) pt = setTimeout(function () { v.playbackRate = FFV; _tip('⏩ ' + FFV + ' 倍速'); }, 500);
    }, { passive: true });
    v.addEventListener('touchmove', function (ev) {
        if (!ev.touches || !ev.touches.length) return;
        var r = rect(), x = ev.touches[0].clientX - r.left;
        if (Math.abs(x - sx) > 12) {
            if (pt) { clearTimeout(pt); pt = null; v.playbackRate = 1; }
            v.currentTime = Math.max(0, Math.min(v.duration || 0, stime + (x - sx) * RATIO));
        }
    }, { passive: true });
    function endTouch() { if (pt) { clearTimeout(pt); pt = null; } v.playbackRate = 1; }
    v.addEventListener('touchend', endTouch);
    v.addEventListener('touchcancel', endTouch);
}
async function _startPlay(pyv, mu) {
    var h = await _loadHls();
    if (!h.ok) {
        _diag({ '失败环节': '加载 hls.js', '已尝试': h.errs, '说明': '四个 CDN 都不通，请检查网络' });
        return null;
    }
    var pl;
    try { pl = await _absPlaylist(mu); }
    catch (e2) {
        _diag({ '失败环节': '取 m3u8 清单', '原因': e2.message,
                '说明': '该站 CDN 有 Referer 防盗链。若页面地址是 data: 或 about:blank，请求不会带 Referer，会直接 404' });
        return null;
    }
    var v = document.createElement('video');
    v.controls = true; v.playsInline = true;
    v.setAttribute('webkit-playsinline', 'true');
    v.setAttribute('x5-playsinline', 'true');
    v.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;background:#000';
    pyv.appendChild(v);
    var burl = URL.createObjectURL(new Blob([pl], { type: 'application/vnd.apple.mpegurl' }));
    var hl = new Hls({ enableWorker: true });
    hl.on(Hls.Events.ERROR, function (e3, dd) {
        if (dd && dd.fatal) _diag({ '失败环节': '播放', '错误': dd.type + '/' + dd.details });
    });
    hl.loadSource(burl);
    hl.attachMedia(v);
    _bindControls(v);
    return v;
}

let pyv = document.querySelector('.artplayer-app');
if (!pyv) { pyv = document.createElement('div'); pyv.className = 'artplayer-app'; document.body.appendChild(pyv); }
/*[修复] 高度兜底：直接算像素高度写回，不依赖 aspect-ratio / min-height 是否被注入 */
