window.addEventListener('resize', _sz);

var _started = false, _ov = null;
function _setOv(t) { if (_ov) _ov.textContent = t; }
async function _go() {
    if (_started) return;
    _started = true;
    if (!uok) {
        _tip('💔未获取到播放链接，请返回重试');
