        return;
    }
    _setOv('⏳正在加载播放器…');
    var v = await _startPlay(pyv, u);
    if (!v) { _setOv('⚠️播放失败，见下方诊断'); return; }
    if (_ov && _ov.parentNode) { try { _ov.parentNode.removeChild(_ov); } catch (e) {} _ov = null; }
    try { v.play(); } catch (e4) {}
}

if (${info['自动播放']=='✅'}) _go();
else {
    _ov = document.createElement('div');
    _ov.className = 'play-indicator';
    _ov.textContent = '▶️';
    pyv.appendChild(_ov);
    pyv.addEventListener('click', function () { _go(); });
}
if (${info['显示链接']=='✅'})
document.getElementById("pyurl").innerHTML=\`<p>播放链接：<span>\${u}</span><button onclick="copyText(this,'before')" style="margin-left: 2ex;">⎘复制</button></p>\`;
	}
setTimeout(init, 50);
</script>
